cat > /tmp/vt-test.mjs << 'EOF'
import { chromium } from 'playwright';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1000, height: 800 } });

const events = [];
page.on('console', (msg) => events.push(msg.text()));

await page.addInitScript(() => {
  window.__vtLog = [];
  const orig = document.startViewTransition?.bind(document);
  if (orig) {
    document.startViewTransition = (cb) => {
      window.__vtLog.push('startViewTransition called');
      const t = orig(cb);
      t.ready.then(() => window.__vtLog.push('ready')).catch(() => {});
      t.finished.then(() => window.__vtLog.push('finished')).catch(() => {});
      return t;
    };
  } else {
    window.__vtLog.push('startViewTransition NOT SUPPORTED');
  }
});

await page.goto('http://localhost:3457/', { waitUntil: 'networkidle' });
console.log('supports startViewTransition:', await page.evaluate(() => typeof document.startViewTransition));

// click first product link
await page.click('.product-card >> nth=0');
await page.waitForURL('**/product/**');
await page.waitForTimeout(800);

const log = await page.evaluate(() => window.__vtLog);
console.log('VT log after forward nav:', JSON.stringify(log));

const html = await page.content();
console.log('has product-hero:', html.includes('product-hero'));

// check computed animation names on pseudo elements isn't directly queryable easily, but check that transition types were passed
const url = page.url();
console.log('current url:', url);

// go back
await page.evaluate(() => window.__vtLog.length = 0);
await page.click('.back-link');
await page.waitForURL('**/');
await page.waitForTimeout(800);
const log2 = await page.evaluate(() => window.__vtLog);
console.log('VT log after back nav:', JSON.stringify(log2));

await browser.close();
EOF
node /tmp/vt-test.mjs
